const locationCards=`<div class="location-grid"><article class="location-card"><p class="eyebrow">United States</p><h3><a href="/online-quran-classes-usa/">Online Quran Classes USA</a></h3><p>One-to-one classes scheduled across Eastern, Central, Mountain and Pacific time, with programs for children and adults.</p><a href="/online-quran-classes-usa/">Explore USA classes →</a></article><article class="location-card"><p class="eyebrow">Australia</p><h3><a href="/online-quran-classes-australia/">Online Quran Classes Australia</a></h3><p>Private Quran lessons arranged around Australian cities and time zones, including male and female tutor requests.</p><a href="/online-quran-classes-australia/">Explore Australia classes →</a></article></div>`;
const locationBody=`${pageHero('Worldwide learning','Online Quran Classes by Location','Find country-specific scheduling guidance for private Quran classes while keeping one consistent course and tutor standard.')} ${breadcrumbs([{name:'Home',href:'/'},{name:'Locations'}])}<section class="section section-paper"><div class="shell article-shell"><div class="answer-box"><strong>Worldwide classes, local-time planning</strong><p>QuranCrest teaches online, so the course structure remains consistent while lesson times are discussed around the learner's city, time zone, age and weekly routine.</p></div><div class="article-body"><h2>Choose your location guide</h2>${locationCards}<h2>What remains consistent in every location</h2><ul class="check-list"><li>Live one-to-one teaching</li><li>A free starting-level assessment</li><li>No card required for the assessment</li><li>Male and female tutor requests</li><li>English and Urdu communication</li><li>Courses from Noorani Qaida to reading, Tajweed, Hifz and Islamic Studies</li></ul><h2>Why city and time zone matter</h2><p>Country names alone are not enough for accurate scheduling. Several countries cover multiple time zones and daylight-saving changes. Share the city and the preferred local lesson window so admissions can check tutor availability correctly.</p><h2>Do learners receive a different curriculum by country?</h2><p>The learner's current level and goal determine the course. Location mainly affects scheduling, communication and practical family routine. A beginner in Australia and a beginner in the United States may both need Noorani Qaida, but their suitable lesson windows will differ.</p><h2>Other countries</h2><p>Families outside the listed location guides can still request an assessment. Share the country, city, time zone and preferred days. Additional country pages will only be published when QuranCrest can provide genuinely useful local information rather than repeating the same page.</p></div></div></section>${cta()}`;
