const blogCards=Object.entries(articles).map(([slug,a])=>`<article class="guide-card"><p class="card-kicker">${a.category} · ${a.readTime}</p><h3><a href="/blog/${slug}/">${a.title}</a></h3><p>${a.description}</p><a href="/blog/${slug}/">Read guide →</a></article>`).join('');
const blogBody=`${pageHero('QuranCrest learning library','Practical Quran Learning Guides','Original guides for beginners, parents and online learners—reviewed against QuranCrest course and tutor standards.')} ${breadcrumbs([{name:'Home',href:'/'},{name:'Blog'}])}<section class="section section-paper"><div class="shell"><div class="section-heading"><p class="eyebrow">Seven detailed guides</p><h2>Answers for real learning decisions</h2><p>Start with the question closest to your current need, then follow the connected course and tutor links.</p></div><div class="guide-grid">${blogCards}</div><div class="editorial-box" style="margin-top:2rem"><strong>Editorial standard</strong><p>Guides are written by the QuranCrest Editorial Team and reviewed against published course information, tutor profiles, child-safety standards and common enrollment questions. We avoid guaranteed learning timelines and clearly separate general guidance from individual assessment.</p></div></div></section>${cta()}`;
fs.writeFileSync(path.join(root,'blog','index.html'),layout({title:'Online Quran Learning Blog | QuranCrest Academy',description:'Read practical, original guides about online Quran classes, tutors, fees, Noorani Qaida, Tajweed and safe learning for children and adults.',canonical:'https://qurancrest.com/blog/',body:blogBody}));

const privacyBody=`${pageHero('Privacy and advertising information','Privacy & Cookie Policy','How QuranCrest handles information, cookies, analytics and advertising technologies on its website.')} ${breadcrumbs([{name:'Home',href:'/'},{name:'Privacy & Cookie Policy'}])}<article class="section section-paper"><div class="shell policy article-shell"><p><strong>Last reviewed:</strong> ${today}</p><p>This policy describes information processed through QuranCrest's website and enrollment process. It should be read together with the <a class="text-link" href="/terms/">Terms</a> and <a class="text-link" href="/child-safety/">Child Safety standards</a>.</p><h2>Information you provide</h2><p>Contact and assessment forms may collect a name, email address, phone or WhatsApp number, country, time zone, learner age, course interest, tutor preference and a description of the learner's current level or goal. Do not submit card details, identity documents or unnecessary sensitive information through these forms.</p><h2>How information is used</h2><p>Information is used to respond to enquiries, arrange an assessment, recommend a course, coordinate scheduling, provide learning support, protect the website and understand whether pages and forms work correctly.</p><h2>Forms, email and WhatsApp</h2><p>Website forms may be processed by the configured form service. Messages may be handled through email or WhatsApp. These providers process information under their own privacy terms. Use only the communication channel you are comfortable with.</p><h2>Cookies and similar technologies</h2><p>QuranCrest may use cookies, local storage, pixels, IP addresses or similar technologies for essential website operation, security, analytics, consent choices and advertising. Some technologies are set by third-party providers.</p><h2>Google advertising disclosure</h2><p>If Google AdSense or another Google advertising service is activated, third-party vendors including Google may use cookies to serve ads based on a visitor's prior visits to this website or other websites. Google's use of advertising cookies enables Google and its partners to serve personalised or non-personalised ads, depending on consent, region and account settings.</p><p>Visitors can learn about and control personalised advertising through <a class="text-link" href="https://adssettings.google.com/" rel="nofollow noreferrer">Google Ads Settings</a>. Information about how Google uses data from partner sites is available in <a class="text-link" href="https://policies.google.com/technologies/partner-sites" rel="nofollow noreferrer">Google's partner-site policy</a>.</p><h2>Consent choices</h2><p>Where required, a consent message will be shown before non-essential advertising or analytics technologies are used. Visitors in the EEA, United Kingdom and Switzerland may receive a Google-certified consent-management message. A visitor can accept, reject or manage available choices through that message.</p><h2>Children's information</h2><p>A parent or guardian should manage enrollment for younger learners. QuranCrest does not ask children to submit payment details, identification documents or unrelated personal information during class. Parents should contact the academy if information was submitted incorrectly.</p><h2>Retention and protection</h2><p>Information is kept only as long as reasonably needed for enquiries, enrollment, learning support, legal obligations, security and record management. No online transmission can be promised as completely risk-free, but access should be limited to people and providers who need it for the stated purpose.</p><h2>Your choices</h2><p>You may ask to review or correct contact information, withdraw from non-essential messages, or request deletion where applicable and practical. Browser settings can also block or remove cookies, although some website features may work differently.</p><h2>Policy changes</h2><p>The review date will be updated when data collection, payment, lesson delivery, analytics, advertising or consent processes materially change.</p><h2>Contact</h2><p>For a privacy question or correction request, email <a class="text-link" href="mailto:${email}">${email}</a>.</p></div></article>`;
fs.writeFileSync(path.join(root,'privacy-policy','index.html'),layout({title:'Privacy & Cookie Policy | QuranCrest Academy',description:'Learn how QuranCrest handles forms, personal information, cookies, analytics, advertising and consent choices.',canonical:'https://qurancrest.com/privacy-policy/',body:privacyBody}));

function stripRsc(html){
  return html
    .replace(/<link rel="modulepreload"[^>]*>/g,'')
    .replace(/<script>self\.__VINEXT_RSC_PARAMS__=.*?<\/script>/gs,'')
    .replace(/<script>self\.__VINEXT_RSC_NAV__=.*?<\/script>/gs,'')
    .replace(/<script id="_R_">.*?<\/script>/gs,'')
    .replace(/<script>self\.__VINEXT_RSC_CHUNKS__.*?<\/script>/gs,'')
    .replace(/<script>self\.__VINEXT_RSC_DONE__=.*?<\/script>/gs,'');
}
function enhanceExisting(html){
  html=stripRsc(html);
  if(!html.includes('/assets/seo-refresh.css'))html=html.replace('</head>','<link rel="stylesheet" href="/assets/seo-refresh.css"></head>');
  if(!html.includes('/assets/static-site.js'))html=html.replace('</body>','<script src="/assets/static-site.js" defer></script></body>');
  html=html.replace('<a href="/pricing/" class="">Pricing</a><a href="/resources/"','<a href="/pricing/" class="">Pricing</a><a href="/locations/" class="">Locations</a><a href="/resources/"');
  if(!html.includes('<a href="/child-safety/">Child safety</a><a href="/locations/">Learning locations</a>'))html=html.replace('<a href="/child-safety/">Child safety</a>','<a href="/child-safety/">Child safety</a><a href="/locations/">Learning locations</a>');
  return html;
}

