const sitemap=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${sitemapUrls.map((u,i)=>`  <url><loc>https://qurancrest.com/${u}</loc><lastmod>${isoDate}</lastmod><changefreq>${u.startsWith('blog/')||u==='resources/'?'monthly':'yearly'}</changefreq><priority>${i===0?'1.0':u==='courses/'||u==='locations/'?'0.9':u.includes('privacy')||u.includes('terms')||u.includes('refund')?'0.3':'0.7'}</priority></url>`).join('\n')}\n</urlset>\n`;
fs.writeFileSync(path.join(root,'sitemap.xml'),sitemap);

const deployFiles=new Set(['assets/seo-refresh.css','assets/static-site.js','index.html','about/index.html','resources/index.html','blog/index.html','privacy-policy/index.html','online-quran-classes-usa/index.html','online-quran-classes-australia/index.html','locations/index.html','sitemap.xml',...Object.keys(articles).map(x=>`blog/${x}/index.html`),...htmlFiles.map(file=>path.relative(root,file))]);
for(const rel of deployFiles){
  const src=path.join(root,rel),dst=path.join(root,'dist',rel);fs.mkdirSync(path.dirname(dst),{recursive:true});fs.copyFileSync(src,dst);
}

console.log(`SEO refresh complete: ${Object.keys(articles).length+1} guides/location pages generated, priority pages updated.`);
